"""Documentation that must track the code: the generated graph topology and the mirrored agent guides."""
from pathlib import Path

from langgraph.checkpoint.memory import MemorySaver

from rag_lab.pipeline.graph import workflow

ROOT = Path(__file__).resolve().parent.parent


def test_committed_graph_diagram_matches_the_compiled_graph():
    """docs/architecture.mmd is generated by `make graph`; a changed edge without re-export fails here."""
    generated = workflow.compile(checkpointer=MemorySaver()).get_graph().draw_mermaid()
    committed = (ROOT / "docs" / "architecture.mmd").read_text(encoding="utf-8")
    assert committed == generated, "docs/architecture.mmd is stale: run 'make graph' and commit the result"


def test_every_graph_node_appears_in_the_hand_drawn_diagrams():
    nodes = {n for n in workflow.compile(checkpointer=MemorySaver()).get_graph().nodes if not n.startswith("__")}
    for doc in ("CLAUDE.md", "README.md"):
        text = (ROOT / doc).read_text(encoding="utf-8")
        missing = sorted(n for n in nodes if f"[{n}]" not in text)
        assert not missing, f"{doc} diagram is missing nodes: {missing}"


def test_agent_guides_are_byte_identical():
    """CLAUDE.md is the source; AGENTS.md mirrors it for other coding agents."""
    assert (ROOT / "CLAUDE.md").read_bytes() == (ROOT / "AGENTS.md").read_bytes(), "copy CLAUDE.md over AGENTS.md"


def _make_targets() -> tuple[set[str], set[str], set[str]]:
    """(defined targets, .PHONY targets, targets advertised by `make help`)."""
    import re

    makefile = (ROOT / "Makefile").read_text(encoding="utf-8")
    defined = set(re.findall(r"^([a-z][a-z0-9-]*):", makefile, re.MULTILINE))
    phony_line = re.search(r"^\.PHONY:(.*)$", makefile, re.MULTILINE)
    phony = set(phony_line.group(1).split()) if phony_line else set()
    helped = set(re.findall(r'@echo "  make ([a-z][a-z0-9-]*)', makefile))
    helped |= set(re.findall(r'@echo "  make [a-z][a-z0-9-]* / make ([a-z][a-z0-9-]*)', makefile))
    return defined, phony, helped


def test_every_documented_make_command_exists():
    import re

    defined, phony, helped = _make_targets()
    for doc in ("CLAUDE.md", "README.md", "docs/usage.md", "docs/design-overview.md"):
        text = (ROOT / doc).read_text(encoding="utf-8")
        documented = set(re.findall(r"(?m)^\s*make ([a-z][a-z0-9-]*)", text))
        assert documented or doc == "docs/design-overview.md", doc  # prose only: no command blocks
        assert documented <= defined, f"{doc} documents missing targets: {sorted(documented - defined)}"
    assert helped <= defined, f"make help lists missing targets: {sorted(helped - defined)}"


def test_every_make_target_is_phony_and_listed_in_help():
    defined, phony, helped = _make_targets()
    # `ingest` is a documented alias of `sync`; `help` describes itself.
    assert defined - phony == set(), f"targets missing from .PHONY: {sorted(defined - phony)}"
    unlisted = defined - helped - {"help", "ingest"}
    assert not unlisted, f"targets missing from make help: {sorted(unlisted)}"



def test_python_snippets_in_the_makefile_still_run():
    """`make ollama-pull` once read config constants that a refactor removed; every snippet must evaluate."""
    import re
    import subprocess
    import sys

    makefile = (ROOT / "Makefile").read_text(encoding="utf-8")
    snippets = re.findall(r"python -c '([^']+)'", makefile)
    assert snippets
    for code in snippets:
        out = subprocess.run([sys.executable, "-c", code], capture_output=True, text=True, cwd=ROOT)
        assert out.returncode == 0 and out.stdout.strip(), (code, out.stderr)


def test_eval_documentation_tracks_golden_set():
    """Pin the case counts and suite splits in eval/README.md to eval/golden.json so doc drift is prevented."""
    import json
    from collections import Counter

    golden_path = ROOT / "eval" / "golden.json"
    with open(golden_path, encoding="utf-8") as f:
        cases = json.load(f)

    total = len(cases)
    by_suite = Counter(c.get("suite") for c in cases)
    by_split = Counter(c.get("split") for c in cases)
    test_conv = sum(1 for c in cases if c.get("split") == "test" and c.get("suite") == "conversation")

    readme = (ROOT / "eval" / "README.md").read_text(encoding="utf-8")

    assert f"`golden.json` has {total} cases." in readme, f"eval/README.md total case count drifted from {total}"
    assert f"`en` ({by_suite['en']})" in readme, f"eval/README.md suite 'en' count drifted from {by_suite['en']}"
    assert f"`multilingual` ({by_suite['multilingual']}:" in readme, (
        f"eval/README.md suite 'multilingual' count drifted from {by_suite['multilingual']}"
    )
    assert f"`messy` ({by_suite['messy']}:" in readme, f"eval/README.md suite 'messy' count drifted from {by_suite['messy']}"
    assert f"`stress` ({by_suite['stress']}:" in readme, f"eval/README.md suite 'stress' count drifted from {by_suite['stress']}"
    assert f"`graph` ({by_suite['graph']}:" in readme, f"eval/README.md suite 'graph' count drifted from {by_suite['graph']}"
    assert f"`conversation` ({by_suite['conversation']} follow-ups)" in readme, (
        f"eval/README.md suite 'conversation' count drifted from {by_suite['conversation']}"
    )
    assert f"on the current {total} cases" in readme, (
        f"eval/README.md test-split table header drifted from {total} cases"
    )

    # Invariants for the held-out test split vs calibration split
    assert by_split["test"] == 143, f"Unexpected test split count: {by_split['test']}"
    assert by_split["calibration"] == 58, f"Unexpected calibration split count: {by_split['calibration']}"
    assert test_conv == 9, f"Unexpected conversation test count: {test_conv}"

